	/**
	 * この画面を[SRCH_NRML]ステータスに設定します。
	 */
	@SuppressWarnings("deprecation")
	public void setSRCH_NRMLStatus() {
		status = SRCH_NRML;
		setAllStatus(status);
	}

	/**
	 * この画面を[SRCH_CUT]ステータスに設定します。
	 */
	@SuppressWarnings("deprecation")
	public void setSRCH_CUTStatus() {
		status = SRCH_CUT;
		setAllStatus(status);
	}

	/**
	 * この画面を[SRCH_ALL]ステータスに設定します。
	 */
	@SuppressWarnings("deprecation")
	public void setSRCH_ALLStatus() {
		status = SRCH_ALL;
		setAllStatus(status);
	}


	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (SRCH_NRML.equals(status)) {
			setSRCH_NRMLStatus();
		}
		else if (SRCH_CUT.equals(status)) {
			setSRCH_CUTStatus();
		}
		else if (SRCH_ALL.equals(status)) {
			setSRCH_ALLStatus();
		}
	}

